def copyRandomList(head: Optional[Node]) -> Optional[Node]:
    if not head:
        return None
    orig_list = []
    curr = head
    while curr:
        orig_list.append(curr)
        curr = curr.next
    new_list = [Node(node.val) for node in orig_list]
    for i in range(len(orig_list)):
        if i + 1 < len(orig_list):
            new_list[i].next = new_list[i + 1]
        r = orig_list[i].random
        if r is not None:
            r_idx = orig_list.index(r)
            new_list[i].random = new_list[r_idx]
    return new_list[0]

data.generator_code:
def generate(rng, n):
    if n == 0:
        return [[]]
    nodes = []
    for i in range(n):
        val = rng.randint(-10000, 10000)
        rand_idx = None if rng.random() < 0.2 else rng.randint(0, n - 1)
        nodes.append([val, rand_idx])
    return [nodes]

def generate_worst(rng, n):
    if n == 0:
        return [[]]
    nodes = []
    for i in range(n):
        val = rng.randint(-10000, 10000)
        rand_idx = (i + n // 2) % n
        nodes.append([val, rand_idx])
    return [nodes]

