def check(args, got, expected):
    head = args[0]
    if head is None:
        return got is None
    if got is None:
        return False
    orig_nodes = []
    curr = head
    while curr:
        orig_nodes.append(curr)
        curr = curr.next
    new_nodes = []
    curr = got
    while curr:
        new_nodes.append(curr)
        curr = curr.next
    if len(orig_nodes) != len(new_nodes):
        return False
    orig_set = set(orig_nodes)
    orig_map = {node: i for i, node in enumerate(orig_nodes)}
    new_map = {node: i for i, node in enumerate(new_nodes)}
    for i in range(len(orig_nodes)):
        o = orig_nodes[i]
        n = new_nodes[i]
        if n in orig_set:
            return False
        if o.val != n.val:
            return False
        if o.random is None:
            if n.random is not None:
                return False
        else:
            if o.random not in orig_map:
                return False
            target_idx = orig_map[o.random]
            if n.random not in new_map or new_map[n.random] != target_idx:
                return False
    return True

